service.method:
SELECT Q.* , NVL((SELECT COUNT(1) FROM SQNAR WHERE HOUSE_CODE = Q.HOUSE_CODE AND QNA_NUMBER = Q.QNA_NUMBER AND NVL(DEL_FLAG, 'N') = 'N'), 0 ) AS REPLY_CNT
FROM ( SELECT Q.HOUSE_CODE , Q.COMPANY_CODE , Q.QNA_NUMBER , Q.SUBJECT , Q.ATTACH_NO , Q.KEYWORDS , Q.CONTENT , Q.ADD_USER_ID , U.USER_NAME_LOC AS ADD_USER_NAME , Q.ADD_DATE , Q.DEL_FLAG , Q.QNA_COMPANY , Q.ROW_NUM , #DB_OWNER#GETDEPTNAME('#session.HOUSE_CODE#', Q.QNA_COMPANY, Q.QNA_USER_DEPT_CODE, '#session.LANGUAGE#') AS QNA_DEPT_NAME , Q.QNA_TYPE , Q.CHECK_FLAG , Q.STATUS , GETUSERNAME(Q.HOUSE_CODE, Q.COMPANY_CODE, Q.MANAGER, ${session.LANGUAGE}) as MANAGER , MANAGER AS MANAGER_ID , CASE WHEN Q.STATUS IN ('F','A','G','CC') THEN Q.CHANGE_DATE END AS GW_CONFIRM_DATE FROM SQNAQ Q LEFT OUTER JOIN SUSMT U ON Q.HOUSE_CODE = U.HOUSE_CODE AND Q.ADD_USER_ID = U.USER_ID WHERE Q.HOUSE_CODE = ${session.HOUSE_CODE} AND Q.QNA_SYSTEM = $S{session.SYSTEM_TYPE}
AND ( Q.QNA_USER_DEPT_CODE = ${session.DEPARTMENT} OR Q.ADD_USER_ID = ${session.ID} )
AND Q.QNA_COMPANY = ${session.COMPANY_CODE}
AND Q.COMPANY_CODE = ${session.COMPANY_CODE}
AND NVL(Q.DEL_FLAG, 'N') = 'N'
AND Q.QNA_NUMBER LIKE 'CQNA%'
AND Q.QNA_NUMBER LIKE 'LQNA%'
AND Q.ADD_DATE >= $S{F_WRITE_DATE_FROM} AND Q.ADD_DATE <= $S{F_WRITE_DATE_TO} AND Q.STATUS = $S{F_STATUS} AND Q.QNA_USER_DEPT_CODE = ($INS{F_DEPT}) AND UPPER(Q.KEYWORDS) LIKE '%' || UPPER($S{F_KEYWORD}) || '%' AND ( UPPER(Q.KEYWORDS) LIKE '%' || UPPER($S{KEYWORD}) || '%' OR UPPER(Q.SUBJECT) LIKE '%' || UPPER($S{KEYWORD}) || '%' OR UPPER(U.USER_NAME_LOC) LIKE '%' || UPPER($S{KEYWORD}) || '%' AND 1=1 ) ) Q WHERE ( UPPER(Q.QNA_COMPANY) LIKE '%' || UPPER($S{F_USER_COMPANY}) || '%' OR UPPER(Q.QNA_COMPANY_NAME) LIKE '%' || UPPER($S{F_USER_COMPANY}) || '%' AND 1=1 ) AND ( UPPER(Q.ADD_USER_ID) LIKE '%' || UPPER($S{F_ADD_USER}) || '%' OR UPPER(Q.ADD_USER_NAME) LIKE '%' || UPPER($S{F_ADD_USER}) || '%' AND 1=1 ) AND ( 1=1 AND UPPER(Q.MANAGER_ID) LIKE '%' || UPPER($S{F_MANAGER}) || '%' OR UPPER(Q.MANAGER) LIKE '%' || UPPER($S{F_MANAGER}) || '%' ) ORDER BY Q.QNA_NUMBER DESC


SELECT	Q.ATTACH_NO
FROM	SQNAQ Q
WHERE	Q.HOUSE_CODE = ${session.HOUSE_CODE}
  AND   Q.QNA_NUMBER = ${QNA_NUMBER}
  AND	NVL(Q.DEL_FLAG, 'N') = 'N'


SELECT
	*
FROM	SQNAQ 
	WHERE	HOUSE_CODE = ${session.HOUSE_CODE}
	  AND	QNA_NUMBER = 'LINK_' || ${QNA_NUMBER}
	  AND	NVL(DEL_FLAG, 'N') = 'N'


INSERT INTO SQNAQ
	(
		HOUSE_CODE
	,	COMPANY_CODE
	,	QNA_NUMBER
	,	SUBJECT
	,	ATTACH_NO
	,	KEYWORDS
	,	CONTENT
	,	ADD_DATE
	,	ADD_TIME
	,	ADD_USER_ID
	,	CHANGE_DATE
	,	CHANGE_TIME
	,	CHANGE_USER_ID
	,	DEL_FLAG
	,	QNA_COMPANY
	,	QNA_TYPE
	,	QNA_SYSTEM
	,   QNA_USER_DEPT_CODE
	,   CHECK_FLAG
	,	STATUS
	,	ROW_NUM
	)
	VALUES
	(
		${session.HOUSE_CODE}
	,	${session.COMPANY_CODE}
	,	${QNA_NUMBER}
	,	${SUBJECT}
	,	${ATTACH_NO}
	,	${KEYWORDS}
	,	${CONTENT}
	,	${current.DATE}
	,	${current.TIME}
	,	${session.ID}
	,	${current.DATE}
	,	${current.TIME}
	,	${session.ID}
	,	'N'
	,	${session.COMPANY_CODE}
	,	${QNA_TYPE}
	,	${session.SYSTEM_TYPE}
	,   ${session.DEPARTMENT}
	,   'N'
	,	${STATUS}
	,	(
			SELECT
				TO_CHAR(MAX(TO_NUMBER(ROW_NUM)) + 1)
			FROM SQNAQ
			WHERE
				HOUSE_CODE = ${session.HOUSE_CODE}
				AND QNA_NUMBER LIKE ${QNA_DOC_TYPE}
		) 
	)


INSERT INTO SQNAQ
	(
		HOUSE_CODE
	,	COMPANY_CODE
	,	QNA_NUMBER
	,	SUBJECT
	,	ATTACH_NO
	,	KEYWORDS
	,	CONTENT
	,	ADD_DATE
	,	ADD_TIME
	,	ADD_USER_ID
	,	CHANGE_DATE
	,	CHANGE_TIME
	,	CHANGE_USER_ID
	,	DEL_FLAG
	,	QNA_COMPANY
	,	QNA_TYPE
	,	QNA_SYSTEM
	,   QNA_USER_DEPT_CODE
	,   CHECK_FLAG
	)
	VALUES
	(
		${session.HOUSE_CODE}
	,	${session.COMPANY_CODE}
	,	${LINK_QNA_NUMBER}
	,	${SUBJECT}
	,	${ATTACH_NO}
	,	${KEYWORDS}
	,	${LINK_CONTENT}
	,	${current.DATE}
	,	${current.TIME}
	,	${session.ID}
	,	${current.DATE}
	,	${current.TIME}
	,	${session.ID}
	,	'N'
	,	${session.COMPANY_CODE}
	,	${QNA_TYPE}
	,	${session.SYSTEM_TYPE}
	,   ${session.DEPARTMENT}
	,   'N'
	)


SELECT QNA_SEQ FROM SQNAR 
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	AND	QNA_NUMBER = ${QNA_NUMBER}
	AND NVL(DEL_FLAG, 'N') = 'N'
	AND ROWNUM <= 1


UPDATE  SQNAQ
   SET	SUBJECT			= ${SUBJECT}
    ,	COMPANY_CODE	= ${session.COMPANY_CODE}
	,	ATTACH_NO		= ${ATTACH_NO}
    ,	KEYWORDS 		= ${KEYWORDS}
    ,	CONTENT 		= ${CONTENT}
    ,	CHANGE_DATE 	= ${current.DATE}
	,	CHANGE_TIME 	= ${current.TIME}
	,	CHANGE_USER_ID 	= ${session.ID}
	,	QNA_TYPE  		= ${QNA_TYPE}
	,	STATUS			= ${STATUS}
 WHERE	HOUSE_CODE 		= ${session.HOUSE_CODE}
   AND	QNA_NUMBER 		= ${QNA_NUMBER}
   AND	ADD_USER_ID		= ${session.ID}


UPDATE  SQNAQ
   SET	SUBJECT 	= ${SUBJECT}
    ,	COMPANY_CODE = ${session.COMPANY_CODE}
	,	ATTACH_NO 	= ${ATTACH_NO}
    ,	KEYWORDS 	= ${KEYWORDS}
    ,	CONTENT 	= ${LINK_CONTENT}
    ,	CHANGE_DATE = ${current.DATE}
	,	CHANGE_TIME = ${current.TIME}
	,	CHANGE_USER_ID = ${session.ID}
	,	QNA_TYPE  = ${QNA_TYPE}
 WHERE	HOUSE_CODE 	= ${session.HOUSE_CODE}
   AND	QNA_NUMBER 	= ${LINK_QNA_NUMBER}
   AND	ADD_USER_ID	= ${session.ID}


INSERT INTO SQNAR
	(
		HOUSE_CODE
	,	QNA_NUMBER
	,	QNA_SEQ
	,	ATTACH_NO
	,	CONTENT
	,	ADD_DATE
	,	ADD_TIME
	,	ADD_USER_ID
	,	CHANGE_DATE
	,	CHANGE_TIME
	,	CHANGE_USER_ID
	,	DEL_FLAG
	,	QNA_COMPANY
	)
	VALUES
	(
		${session.HOUSE_CODE}
	,	${QNA_NUMBER}
	,	(SELECT NVL(MAX(CAST(QNAR.QNA_SEQ AS INT)),0) + 1 
	     FROM   SQNAR QNAR 
	     WHERE  QNAR.HOUSE_CODE = ${session.HOUSE_CODE} 
	     AND    QNAR.QNA_NUMBER = ${QNA_NUMBER})
	,	${ATTACH_NO}
	,	${CONTENT}
	,	${current.DATE}
	,	${current.TIME}
	,	${session.ID}
	,	${current.DATE}
	,	${current.TIME}
	,	${session.ID}
	,	'N'
	,	${session.COMPANY_CODE}
	)


UPDATE  SQNAQ
   SET	DEL_FLAG 	= 'Y'
    ,	CHANGE_DATE = ${current.DATE}
	,	CHANGE_TIME = ${current.TIME}
	,	CHANGE_USER_ID = ${session.ID}			   
 WHERE	HOUSE_CODE 	= ${session.HOUSE_CODE}
   AND	QNA_NUMBER 	= ${QNA_NUMBER}



   AND	ADD_USER_ID	= ${session.ID}


DELETE FROM SQNAQ Q
   WHERE QNA_NUMBER = 'LINK_' || ${QNA_NUMBER}



   AND	ADD_USER_ID	= ${session.ID}


UPDATE  SQNAR
   SET	DEL_FLAG 	= 'Y'
    ,	CHANGE_DATE = ${current.DATE}
	,	CHANGE_TIME = ${current.TIME}
	,	CHANGE_USER_ID = ${session.ID}			   
 WHERE	HOUSE_CODE 	= ${session.HOUSE_CODE}
   AND	QNA_NUMBER 	= ${QNA_NUMBER}
   AND	QNA_SEQ = ${QNA_SEQ}



   AND	ADD_USER_ID	= ${session.ID}


UPDATE SQNAQ
SET CHECK_FLAG = ${CHECK_FLAG}
	, STATUS = ${STATUS}
	, CHANGE_DATE = ${current.DATE}
	, CHANGE_TIME = ${current.TIME}
	, CHANGE_USER_ID = ${session.ID}
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND	QNA_NUMBER = ${QNA_NUMBER}
	AND NVL(DEL_FLAG, 'N') = 'N'
	AND NVL(CHECK_FLAG, 'N') <> 'Y'
	AND STATUS IN ('L', 'A')


UPDATE SQNAQ
   SET STATUS = ${STATUS}
     , CHANGE_DATE = ${current.DATE}
     , CHANGE_TIME = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}
 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND QNA_NUMBER = ${QNA_NUMBER}
   AND NVL(DEL_FLAG, 'N') = 'N'
   AND STATUS = 'G'
   AND MANAGER = ${session.ID}

SELECT Q.* , NVL((SELECT COUNT(1) FROM SQNAR WHERE HOUSE_CODE = Q.HOUSE_CODE AND QNA_NUMBER = Q.QNA_NUMBER AND NVL(DEL_FLAG, 'N') = 'N'), 0 ) AS REPLY_CNT
FROM ( SELECT Q.HOUSE_CODE , Q.COMPANY_CODE , Q.QNA_NUMBER , Q.SUBJECT , Q.ATTACH_NO , Q.KEYWORDS , Q.ADD_USER_ID , U.USER_NAME_LOC AS ADD_USER_NAME , Q.ADD_DATE , Q.DEL_FLAG , Q.QNA_COMPANY , #DB_OWNER#GETDEPTNAME('#session.HOUSE_CODE#', Q.QNA_COMPANY, Q.QNA_USER_DEPT_CODE, '#session.LANGUAGE#') AS QNA_DEPT_NAME , Q.QNA_TYPE , Q.CHECK_FLAG , Q.ROW_NUM FROM SQNAQ Q LEFT OUTER JOIN SUSMT U ON Q.HOUSE_CODE = U.HOUSE_CODE AND Q.ADD_USER_ID = U.USER_ID WHERE Q.HOUSE_CODE = ${session.HOUSE_CODE} AND Q.QNA_SYSTEM = $S{session.SYSTEM_TYPE}
AND (Q.QNA_USER_DEPT_CODE = ${session.DEPARTMENT} or Q.ADD_USER_ID = ${session.ID} )
AND Q.QNA_COMPANY = ${session.COMPANY_CODE}
AND Q.COMPANY_CODE = ${session.COMPANY_CODE}
AND NVL(Q.DEL_FLAG, 'N') = 'N'
AND Q.QNA_NUMBER LIKE 'CQNA%'
AND Q.QNA_NUMBER LIKE 'LQNA%'
AND Q.ADD_DATE >= $S{F_WRITE_DATE_FROM} AND Q.ADD_DATE <= $S{F_WRITE_DATE_TO} AND UPPER(Q.KEYWORDS) LIKE '%' || UPPER($S{F_KEYWORD}) || '%' AND ( UPPER(Q.KEYWORDS) LIKE '%' || UPPER($S{KEYWORD}) || '%' OR UPPER(Q.SUBJECT) LIKE '%' || UPPER($S{KEYWORD}) || '%' OR UPPER(U.USER_NAME_LOC) LIKE '%' || UPPER($S{KEYWORD}) || '%' AND 1=1 ) ) Q WHERE ( UPPER(Q.QNA_COMPANY) LIKE '%' || UPPER($S{F_USER_COMPANY}) || '%' OR UPPER(Q.QNA_COMPANY_NAME) LIKE '%' || UPPER($S{F_USER_COMPANY}) || '%' AND 1=1 ) AND ( UPPER(Q.ADD_USER_ID) LIKE '%' || UPPER($S{F_ADD_USER}) || '%' OR UPPER(Q.ADD_USER_NAME) LIKE '%' || UPPER($S{F_ADD_USER}) || '%' AND 1=1 ) ORDER BY Q.QNA_NUMBER DESC


UPDATE  SQNAQ
   SET	STATUS			= ${STATUS}
 WHERE	HOUSE_CODE 		= ${session.HOUSE_CODE}
   AND	QNA_NUMBER 		= ${QNA_NUMBER}


UPDATE SQNAQ
SET MANAGER = ${MANAGER}
WHERE	HOUSE_CODE 		= ${session.HOUSE_CODE}
   AND	QNA_NUMBER 		= ${QNA_NUMBER}


SELECT
	Q.QNA_NUMBER
	, Q.STATUS
	, Q.MANAGER
	, NVL(Q.CHECK_FLAG, 'N') AS CHECK_FLAG
FROM SQNAQ Q
WHERE Q.HOUSE_CODE = ${session.HOUSE_CODE}
  AND Q.COMPANY_CODE = ${session.COMPANY_CODE}
  AND Q.QNA_NUMBER = ${QNA_NUMBER}
  AND NVL(Q.DEL_FLAG, 'N') = 'N'


UPDATE SQNAQ
   SET MANAGER = ${session.ID}
     , STATUS = 'G'
     , CHANGE_DATE = ${current.DATE}
     , CHANGE_TIME = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}
 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND QNA_NUMBER = ${QNA_NUMBER}
   AND NVL(DEL_FLAG, 'N') = 'N'
   AND STATUS = 'F'


UPDATE SQNAQ
   SET STATUS = 'G'
     , CHANGE_DATE = ${current.DATE}
     , CHANGE_TIME = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}
 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND QNA_NUMBER = ${QNA_NUMBER}
   AND NVL(DEL_FLAG, 'N') = 'N'
   AND STATUS IN ('L', 'A')
   AND NVL(CHECK_FLAG, 'N') <> 'Y'
   AND MANAGER = ${session.ID}


		SELECT RESPONSIBILITY
 		FROM   SUSMT
		WHERE  HOUSE_CODE   = ${session.HOUSE_CODE}
		AND	   COMPANY_CODE = ${session.COMPANY_CODE}
		AND    USER_ID 		= ${session.ID}


SELECT
	SMR_NUMBER
	, SMR_STATUS
	, SOURCE_NO
FROM SSIAD
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
  AND COMPANY_CODE = ${session.COMPANY_CODE}
  AND SOURCE_NO = ${SOURCE_NO}
  AND NVL(DEL_FLAG, 'N') = 'N'
ORDER BY SMR_NUMBER DESC
